<?php
require dirname(__DIR__, 2) . '/app/bootstrap.php'; require_admin();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf((string)($_POST['csrf']??''));$id=(int)($_POST['id']??0);$output=json_encode(['rod'=>trim($_POST['rod']??''),'egi'=>trim($_POST['egi']??''),'pe'=>trim($_POST['pe']??''),'leader'=>trim($_POST['leader']??'')],JSON_UNESCAPED_UNICODE);
$data=[':priority'=>(int)($_POST['priority']??100),':season'=>($_POST['season']??'')?:null,':field'=>($_POST['field_type']??'')?:null,':depth'=>($_POST['depth_band']??'')?:null,':wind'=>($_POST['wind_band']??'')?:null,':current'=>($_POST['current_band']??'')?:null,':size'=>($_POST['target_size']??'')?:null,':output'=>$output,':rationale'=>trim($_POST['rationale']??''),':source'=>trim($_POST['source_note']??''),':enabled'=>isset($_POST['enabled'])?1:0];
if($id){$data[':id']=$id;$pdo->prepare("UPDATE simulator_rules SET priority=:priority,season=:season,field_type=:field,depth_band=:depth,wind_band=:wind,current_band=:current,target_size=:size,output=:output,rationale=:rationale,source_note=:source,enabled=:enabled WHERE id=:id")->execute($data);}else{$pdo->prepare("INSERT INTO simulator_rules(priority,season,field_type,depth_band,wind_band,current_band,target_size,output,rationale,source_note,enabled) VALUES(:priority,:season,:field,:depth,:wind,:current,:size,:output,:rationale,:source,:enabled)")->execute($data);}header('Location:/admin/rules.php');exit;}
if(isset($_GET['delete'])){verify_csrf((string)($_GET['token']??''));$pdo->prepare("DELETE FROM simulator_rules WHERE id=?")->execute([(int)$_GET['delete']]);header('Location:/admin/rules.php');exit;}
$edit=null;if(isset($_GET['edit'])){$s=$pdo->prepare("SELECT * FROM simulator_rules WHERE id=?");$s->execute([(int)$_GET['edit']]);$edit=$s->fetch();if($edit){$edit['out']=json_decode($edit['output'],true)?:[];}}
$rows=$pdo->query("SELECT id,priority,season,field_type,depth_band,wind_band,current_band,enabled,updated_at FROM simulator_rules ORDER BY priority,id")->fetchAll();
