<label>ロッド<input name="rod" value="<?=htmlspecialchars($edit['out']['rod']??'',ENT_QUOTES,'UTF-8')?>"></label><label>エギ<input name="egi" value="<?=htmlspecialchars($edit['out']['egi']??'',ENT_QUOTES,'UTF-8')?>"></label><label>PE<input name="pe" value="<?=htmlspecialchars($edit['out']['pe']??'',ENT_QUOTES,'UTF-8')?>"></label><label>リーダー<input name="leader" value="<?=htmlspecialchars($edit['out']['leader']??'',ENT_QUOTES,'UTF-8')?>"></label><label>理由<textarea required name="rationale"><?=htmlspecialchars($edit['rationale']??'',ENT_QUOTES,'UTF-8')?></textarea></label><label>根拠メモ<textarea name="source_note"><?=htmlspecialchars($edit['source_note']??'',ENT_QUOTES,'UTF-8')?></textarea></label><label><input type="checkbox" name="enabled" <?=($edit['enabled']??1)?'checked':''?>> 有効</label><button>保存</button></form>
<table><tr><th>優先</th><th>季節</th><th>場所</th><th>水深</th><th>風</th><th>潮</th><th>有効</th><th></th></tr><?php foreach($rows as $r):?><tr><td><?=$r['priority']?></td><td><?=$r['season']?:'*'?></td><td><?=$r['field_type']?:'*'?></td><td><?=$r['depth_band']?:'*'?></td><td><?=$r['wind_band']?:'*'?></td><td><?=$r['current_band']?:'*'?></td><td><?=$r['enabled']?'ON':'OFF'?></td><td><a href="?edit=<?=$r['id']?>">編集</a> / <a href="?delete=<?=$r['id']?>&token=<?=urlencode(csrf_token())?>" onclick="return confirm('削除しますか？')">削除</a></td></tr><?php endforeach;?></table></main></body></html>